import { lookup as dnsLookup } from 'node:dns/promises'

/**
 * DNS for the outbound address guard. Every resolved address is checked, so
 * `all: true` is load-bearing: taking only the first record would let a
 * multi-record name hide a private address behind a public one.
 */
async function resolveNetworkAddresses(host: string): Promise<string[]> {
  const records = await dnsLookup(host, { all: true, verbatim: true })
  return records.map(record => record.address)
}
