/** UA12.28 — the most of a host-gate card's deny note the card's refusal quotes; P6.864's own bound (`base-agent.ts` `MAX_PERMISSION_ANSWER_NOTE_CHARS`). */
const MAX_HOST_CARD_NOTE_CHARS = 1200

/**
 * UA12.76 — appended for F1.496's reason (every docs-cited line keeps its number). The text of every final assistant row
 * after `turnStartFinalMessageId` (the last final row before the turn began; `undefined` when there was none), with the
 * predicate {@link SessionManager}'s `getLastFinalAssistantMessageId` uses, so the last entry is the turn's `finalText`.
 * When the start marker is no longer in the transcript the turn's rows cannot be told from earlier ones, so only the
 * final message itself is returned — never an earlier turn's text.
 */
function turnFinalAssistantTexts(messages: readonly Message[], turnStartFinalMessageId: string | undefined, finalMessageId: string): string[] {
  const start = turnStartFinalMessageId === undefined ? -1 : messages.findIndex(m => m.id === turnStartFinalMessageId)
  const rows = turnStartFinalMessageId !== undefined && start === -1
    ? messages.filter(m => m.id === finalMessageId)
    : messages.slice(start + 1).filter(m => m.role === 'assistant' && !m.isIntermediate)
  return rows.map(m => m.content)
}

/**
 * F1.1092 — the sandbox divergence notice's stable opening, restated from its only emitter
 * (`noteResolvedSandboxPolicy`, codex-agent.ts, which does not export it — the same restatement P3.267 accepted
 * for the config-writer prefixes). Drift is pinned in codex-saved-notice-restated.test.ts, which reads the
 * emitter's source.
 */
const CODEX_SANDBOX_DIVERGENCE_NOTICE_OPENING = 'Codex is not running under the sandbox mode this app asked for.'

/**
 * F1.1092 — whether the warning belongs to the relaunch-restatement family: the warning surfaces the codex agent
 * says once per process (F1.734) and an app relaunch therefore restates on the resumed session's first turn. ONLY
 * that family skips an identical saved row — codex re-says everything else per attempt, and a repeat there is a NEW
 * event the user must see again: `UserPromptSubmit hook: <systemMessage>` is yielded on EVERY blocked prompt (the
 * branch is live — `hookBlockEndsTurn('UserPromptSubmit')` is true), and the uncarried image/document diagnostics
 * are yielded on every prompt that carries one. codex-saved-notice-restated.test.ts pins a repeat of each.
 */
function isCodexRelaunchRestatementNotice(message: string): boolean {
  if (message.startsWith(CODEX_SANDBOX_DIVERGENCE_NOTICE_OPENING)) return true
  // The config-writer diagnostic family's machine prefix (`CODEX_CONFIG_WRITER_USER_FACING_PREFIXES`,
  // codex-agent.ts); shared's codex-operator-notice-lift.test.ts drives the REAL formatter against this spelling.
  if (message.startsWith('codex-sandbox-egress-denied:')) return true
  // codex's own model-metadata constant, matched on BOTH halves exactly as the agent matches it
  // (`isCodexModelMetadataConstantWarning`, codex-agent.ts, P6.580): a message that merely mentions
  // metadata is a different warning.
  const lowered = message.toLowerCase()
  if (lowered.includes('model metadata') && lowered.includes('not found')) return true
  // The host caveat that constant drags along (`noteCodexModelMetadataConstantOnce`, codex-agent.ts, i18n
  // `chat.codexModelMetadata.constant`): its opening is derived from the key itself with an empty model and cut
  // at the interpolation, so both locales — and any rewording — follow the key instead of a restated copy.
  if (!i18n.isInitialized) setupI18n()
  const probe: unknown = i18n.t('chat.codexModelMetadata.constant', { model: '' })
  if (typeof probe === 'string') {
    const cut = probe.indexOf('`')
    // cut > 0: the sentence must say something before the model name; a key reworded to open with the
    // interpolation has no stable opening and matches nothing rather than everything.
    if (cut > 0 && message.startsWith(probe.slice(0, cut))) return true
  }
  return false
}

/**
 * F1.1092 (origin DN-050, 2026-09-26) — whether a codex warning restates one already SAVED in the transcript, so
 * the host neither saves it again nor shows it again. The match is scoped to the relaunch-restatement family the
 * row names (`isCodexRelaunchRestatementNotice` above): the notices the codex agent says once per process
 * (F1.734 — the sandbox divergence notice, `codex-sandbox-egress-denied`, the first model-metadata warning with
 * the caveat beside it), which an app relaunch restates on the resumed session's first turn. Decided under the
 * owner's rule (2026-10-08, simplest), narrowed by the repair: skip a warning row identical to a saved one, on
 * codex, ONLY inside that family — the first general match also swallowed a repeated `UserPromptSubmit hook: …`
 * block line and a repeated uncarried-attachment diagnostic, which codex yields per attempt (the hook-block path
 * exists on codex too, codex-agent.ts), so they pass as new events on codex as on Pi and Claude.
 */
export function codexRestatesSavedWarning(
  provider: string | undefined,
  messages: ReadonlyArray<{ role: string; infoLevel?: string; content?: unknown }>,
  event: { level?: string; message: string },
): boolean {
  if (provider !== 'codex-runtime' || event.level !== 'warning') return false
  if (!isCodexRelaunchRestatementNotice(event.message)) return false
  return messages.some(message => message.role === 'info' && message.infoLevel === 'warning' && message.content === event.message)
}
